"""Provider-neutral perception contracts.

Providers return pixel-space candidates without VIR IDs. The normalization
layer validates them, converts coordinates to [0, 1], applies deterministic
spatial ordering, and only then creates Phase 1 ``DetectedObject`` and
``DetectedText`` instances.
"""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Protocol, TYPE_CHECKING, runtime_checkable

if TYPE_CHECKING:
    from .image import LoadedImage


@dataclass(frozen=True)
class RawObject:
    label: str
    confidence: float
    bbox_xyxy: tuple[float, float, float, float]


@dataclass(frozen=True)
class RawText:
    text: str
    confidence: float
    polygon: tuple[tuple[float, float], ...]
    language: str = "unknown"


@dataclass(frozen=True)
class ModelArtifact:
    path: Path
    size_bytes: int
    sha256: str

    def to_dict(self) -> dict:
        return {"path": str(self.path), "size_bytes": self.size_bytes, "sha256": self.sha256}


@dataclass(frozen=True)
class ProviderInfo:
    backend: str
    model: str
    requested_device: str
    device: str
    package_version: str | None
    artifacts: tuple[ModelArtifact, ...] = ()

    def to_dict(self) -> dict:
        return {
            "backend": self.backend,
            "model": self.model,
            "requested_device": self.requested_device,
            "device": self.device,
            "package_version": self.package_version,
            "artifacts": [item.to_dict() for item in self.artifacts],
        }


@runtime_checkable
class ObjectDetector(Protocol):
    """A lazy local detector. ``load`` and ``detect`` are timed separately."""

    @property
    def info(self) -> ProviderInfo: ...

    def load(self) -> None: ...

    def detect(self, image: LoadedImage) -> tuple[RawObject, ...]: ...


@runtime_checkable
class OCRProvider(Protocol):
    """A lazy local OCR backend that does not assign VIR text IDs."""

    @property
    def info(self) -> ProviderInfo: ...

    def load(self) -> None: ...

    def extract(self, image: LoadedImage) -> tuple[RawText, ...]: ...
